for file in [s/'ledger.md',p/'project01-mvp/arc06-fit-and-finish/ledger.md',p/'project01-mvp/ledger.md']:
 before=rows(old(file));now=rows(file.read_text());assert set(before)==set(now)
 for key in before:assert before[key][:5]==now[key][:5],key
 if file!=s/'ledger.md':assert before==now
 print(file.relative_to(p),'rows',len(now),'status',{x:sum(v[5].strip()==x for v in now.values()) for x in ['done','open']})
current=rows((s/'ledger.md').read_text());assert {k for k,v in current.items() if v[5].strip()=='done'}=={'QG-01','QG-02','QG-04','QG-05','QG-06','QG-07'}
